-- A tiny example of the Brunel data (Sessions 1 to 7), so the stack comes up
-- before your team swaps in its own source. Real rows from the Brunel
-- Supply Chain Logistics Problem dataset (Figshare 7558679 v2, CC BY 4.0):
-- 60 orders, 22 plant ports, 57 products per plant, 30 freight rates.

CREATE TABLE orders ( order_id TEXT,  order_date TEXT,  origin_port TEXT,  carrier TEXT,  tpt BIGINT,  service_level TEXT,  ship_ahead_day_count BIGINT,  ship_late_day_count BIGINT,  customer TEXT,  product_id TEXT,  plant_code TEXT,  destination_port TEXT,  unit_quantity BIGINT,  weight TEXT);
CREATE TABLE plant_ports ( plant_code TEXT,  port TEXT);
CREATE TABLE products_per_plant ( plant_code TEXT,  product_id TEXT);
CREATE TABLE freight_rates ( rate_id BIGINT,  carrier TEXT,  orig_port_cd TEXT,  dest_port_cd TEXT,  minm_wgh_qty TEXT,  max_wgh_qty TEXT,  svc_cd TEXT,  minimum_cost FLOAT,  rate TEXT,  mode_dsc TEXT,  tpt_day_cnt BIGINT,  carrier_type TEXT);
